from concurrent.futures import ThreadPoolExecutor
import hashlib
import json
from pathlib import Path
import subprocess
import sys

import peer_probes
import probe


def record(result):
    assert result['exit_code'] == 0, result
    return json.loads(result['stdout'])


def safe(result, receipt=None):
    row = record(result)
    assert row['verdict'] == 'SAFE', row
    if receipt:
        assert row['receipt'] == receipt, row


def refused(result):
    assert record(result)['verdict'] == 'NOT-SAFE', result


def deleted(result):
    assert result['exit_code'] == 0 and '\tDELETED\t' in result['stdout'], result


def check(name, result):
    if name == 'concurrent_same_target':
        assert result['deleted_workers'] == 1 and not result['original_exists'], result
    elif name in ('nested_stale', 'nested_pushed'):
        assert result['inner_unpushed'] == '1' and result['inner_dirty'], result
        for output in result['ancestor_verdicts'].values():
            safe(output)
        for output in result['inner_verdicts'].values():
            refused(output)
        deleted(result['quarantine'])
        assert not result['nested_repo_exists_after'], result
    elif name == 'readonly_indexes':
        for item in result['records']:
            expected = item['tool'] != 'souji-census.sh'
            assert item['changed'] == expected, item
            if expected:
                assert any('rename(' in line for line in item['index_trace']), item
    elif name == 'disappearing_git':
        for item in result['records']:
            assert item['unpushed'] == '1' and item['shim_removed'], item
            if 'quarantine' in item['tool']:
                assert item['baseline']['exit_code'] == 3, item
                assert item['attack']['exit_code'] == 0 and '\tSAFE\tmetadata-prune\t' in item['attack']['stdout'] and '\tSKIPPED\tmetadata-prune\t' in item['attack']['stdout'], item
            else:
                refused(item['baseline'])
                safe(item['attack'], 'metadata-prune')
    elif name == 'turkish_locale':
        assert result['case_fold']['stdout'] == 'ıd_empty' and result['target_is_empty_directory'], result
        for item in result['records']:
            if 'quarantine' in item['tool']:
                assert item['attack']['exit_code'] == 3 and 'secrets-refusal' in item['attack']['stdout'], item
            else:
                refused(item['baseline'])
                safe(item['attack'], 'stale')
    elif name in ('revoked_rollback', 'revoked_missing'):
        assert result['mutation_occurred_after_stage3'] and result['unpushed_touching'] == '', result
        deleted(result['quarantine'])
        assert not result['immediately_after']['original_exists'] and not result['immediately_after']['quarantined_payloads'], result
        for output in result['restored_verdicts'].values():
            refused(output)
    elif name == 'sigkill_hold':
        assert result['killed_during_hold'] and result['exit_code'] == -9 and result['staged_bytes_exact'], result
        assert result['original_restart']['exit_code'] == 3 and result['quarantine_restart']['exit_code'] == 3, result
        assert '\tDELETED\t' not in result['original_restart']['stdout'] + result['quarantine_restart']['stdout'], result
    elif name in ('nul_path', 'nul_pin'):
        deleted(result['quarantine'])
        assert not result['target_exists_after'] and not result['quarantine_payloads_after'], result
    elif name == 'ledger_readers':
        assert result['atomic_revocation']['before'] != result['atomic_revocation']['after'] and result['atomic_revocation']['remaining_receipt_rows'] == 0, result
        for output in result['outputs']:
            safe(output, 'moved-to-obsidian')
        for pair in result['fresh_after_revocation']:
            for output in pair.values():
                refused(output)
        assert result['vaults_survive'], result
    elif name == 'ledger_quarantine':
        deleted(result['quarantine'])
        assert result['atomic_revocation']['remaining_receipt_rows'] == 0 and result['vault_survives'], result
        assert not result['immediately_after']['original_exists'] and not result['immediately_after']['staged_files'], result
        for output in result['fresh_after_revocation'].values():
            refused(output)
    else:
        raise AssertionError(name)


CASES = {name: probe.CASES[name] for name in ['concurrent_same_target', 'nested_stale', 'nested_pushed', 'readonly_indexes']}
CASES.update(peer_probes.CASES)


def run_one(pair):
    name, function = pair
    result = function()
    check(name, result)
    return name, result


if __name__ == '__main__':
    evidence = Path(subprocess.check_output(['mktemp', '-d', '-p', '/var/tmp', 'souji-r9-s08-evidence.XXXXXX'], text=True).strip())
    with ThreadPoolExecutor(max_workers=10) as pool:
        results = dict(pool.map(run_one, CASES.items()))
    report = dict(tool_dir=str(probe.BASELINE), tool_sha256={p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in probe.BASELINE.glob('souji-*.sh')}, cases=results,
                  assertions_passed=len(results), peer_defect_claims=7, confirmed_peer_claims=7, not_reproduced_peer_claims=0,
                  unsafe_authorization_classes=6, separate_readonly_write_classes=1, direct_verifier_false_safe_pairs=10,
                  quarantine_false_delete_scenarios=7, propagated_unsafe_metadata_safe_without_delete=1,
                  verifier_index_write_scenarios=2, engine_safety_verdict_disagreements=0,
                  ancestor_descendant_contradiction_pairs=4, revoked_receipt_delete_contradiction_scenarios=3,
                  malformed_list_authorization_contradiction_scenarios=2,
                  counting_note='Only this fresh aggregate run is counted; preparatory/repeated probes are not added. Same root cause across tools/variants remains one defect claim. No complete negative peer battery is inferred from two independent spot controls.')
    output = evidence / 'results.json'
    output.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n')
    print(json.dumps({key: value for key, value in report.items() if key != 'cases'} | {'evidence': str(output)}, indent=2))
